/** Dedup wariantów per PN w obrębie serii — zachowuje wpis z najpełniejszymi atrybutami. */
function enrich(v: ProductVariant): ProductVariant {
  const attrs: Record<string, string> = { ...v.attributes }
  // Uzupełnij brakujący Rozmiar z override (jeśli znamy go ze starych danych)
  if (!attrs['Rozmiar'] && SIZE_OVERRIDES[v.partNumber]) {
    attrs['Rozmiar'] = SIZE_OVERRIDES[v.partNumber]
  }
  // Dodaj liczbę etykiet w rolce, jeśli mamy w mapie historycznej
  const qty = QTY_OVERRIDES[v.partNumber]
  if (qty && !attrs['Etykiet w rolce']) {
    attrs['Etykiet w rolce'] = `${qty} szt.`
  }
  return attrs === v.attributes ? v : { ...v, attributes: attrs }
}

function dedupVariants(variants: ProductVariant[] | undefined): ProductVariant[] | undefined {
  if (!variants) return variants
  const byPn = new Map<string, ProductVariant>()
  for (const raw of variants) {
    const v = enrich(raw)
    const existing = byPn.get(v.partNumber)
    if (!existing) {
      byPn.set(v.partNumber, v)
      continue
    }
    // Konflikt PN — wybierz wpis z większą liczbą atrybutów (np. z Rdzeń vs bez)
    const existingAttrs = Object.keys(existing.attributes).length
    const candidateAttrs = Object.keys(v.attributes).length
    if (candidateAttrs > existingAttrs) byPn.set(v.partNumber, v)
  }
  return Array.from(byPn.values())
}

